+const TestWatcher = require('../TestWatcher');
+
+let workerFarmMock;
+
+jest.mock('worker-farm', () => {
+  const mock = jest.fn(
+    (options, worker) => workerFarmMock = jest.fn(
+      (data, callback) => require(worker)(data, callback),
+    ),
+  );
+  mock.end = jest.fn();
+  return mock;
+});
+
+jest.mock('../TestWorker', () => {});
+jest.mock('../reporters/DefaultReporter');
