-        const diffMark = chalk.yellow(`@@ ${diffMarkOld} ${diffMarkNew} @@\n`);
-
+      .hunks.map((hunk: Hunk) => {
-        return diffMark + lines;
+        return shouldShowPatchMarks(hunk, oldLinesCount)
+          ? createPatchMark(hunk) + lines
